import React, { useState, useEffect } from 'react';
import { Modal, Button, Form } from 'react-bootstrap';

function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [currentProduct, setCurrentProduct] = useState(null);
  const [modalLoading, setModalLoading] = useState(false);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    setLoading(true);
    try {
      const res = await fetch('http://localhost/api/productes');
      if (!res.ok) throw new Error('Error al obtenir els productes');
      const data = await res.json();
      setProducts(data.dades || []);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setError(err.message);
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Segur que vols eliminar aquest producte?')) return;

    try {
      const res = await fetch(`http://localhost/api/productes/${id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Accept': 'application/json'
        }
      });

      const data = await res.json();

      if (!res.ok || !data.exit) {
        alert(data.missatge || 'Error eliminant el producte');
      } else {
        alert('Producte eliminat correctament');
        fetchProducts();
      }
    } catch (err) {
      console.error(err);
      alert('Error de connexió');
    }
  };

  const handleEdit = (product) => {
    setCurrentProduct(product);
    setShowModal(true);
  };

  const handleModalClose = () => {
    setShowModal(false);
    setCurrentProduct(null);
  };

  const handleModalSubmit = async (e) => {
    e.preventDefault();
    setModalLoading(true);

    try {
      const res = await fetch(`http://localhost/api/productes/${currentProduct.id}`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(currentProduct)
      });

      const data = await res.json();

      if (!res.ok || !data.exit) {
        alert(data.missatge || 'Error actualitzant el producte');
      } else {
        alert('Producte actualitzat correctament');
        fetchProducts();
        handleModalClose();
      }
    } catch (err) {
      console.error(err);
      alert('Error de connexió');
    }

    setModalLoading(false);
  };

  const handleChange = (e) => {
    setCurrentProduct({
      ...currentProduct,
      [e.target.name]: e.target.value
    });
  };

  if (loading) return <p>Carregant productes...</p>;
  if (error) return <p>Error: {error}</p>;
  if (products.length === 0) return <p>No hi ha productes disponibles.</p>;

  return (
    <div className="row">
      {products.map(product => (
        <div key={product.id} className="col-md-4 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5 className="card-title">{product.nom}</h5>
              <p className="card-text">{product.descripcio}</p>
              <p className="card-text"><strong>Referència:</strong> {product.referencia}</p>
              <p className="card-text"><strong>Quantitat:</strong> {product.quantitat}</p>
              <Button variant="warning" size="sm" className="me-2" onClick={() => handleEdit(product)}>Editar</Button>
              <Button variant="danger" size="sm" onClick={() => handleDelete(product.id)}>Eliminar</Button>
            </div>
          </div>
        </div>
      ))}

      {/* Modal d'edició */}
      <Modal show={showModal} onHide={handleModalClose}>
        <Form onSubmit={handleModalSubmit}>
          <Modal.Header closeButton>
            <Modal.Title>Editar Producte</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form.Group className="mb-3">
              <Form.Label>Nom</Form.Label>
              <Form.Control
                type="text"
                name="nom"
                value={currentProduct?.nom || ''}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Descripció</Form.Label>
              <Form.Control
                type="text"
                name="descripcio"
                value={currentProduct?.descripcio || ''}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Referència</Form.Label>
              <Form.Control
                type="text"
                name="referencia"
                value={currentProduct?.referencia || ''}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Quantitat</Form.Label>
              <Form.Control
                type="number"
                name="quantitat"
                value={currentProduct?.quantitat || 0}
                onChange={handleChange}
                required
              />
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleModalClose}>Cancelar</Button>
            <Button type="submit" variant="primary" disabled={modalLoading}>
              {modalLoading ? 'Actualitzant...' : 'Guardar'}
            </Button>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  );
}

export default ProductsList;
